import com.mongodb.client.model.Filters;
import com.mongodb.client.model.Updates;

public class Main {
  public static void main(String[] args) {
      // En Java, los paquetes Filters y Updates nos ahorran tener que escribir 
      // los operadores como '$set' de forma plana propensa a typos:

      collection.updateOne(
          Filters.eq("direccion", "Valley 345"),
          Updates.set("direccion", "Canyon 123")
      );

      System.out.println("Los clientes fueron redireccionados.");
  }
}
